'use strict';
// Isolated, in-memory technical-mode example. No service control or backend enforcement.
const technicalLabels={off:['Выключен','Off'],pending:['Команда принята · остановка не подтверждена','Command accepted · shutdown unconfirmed'],partial:['Остановка подтверждена не полностью','Shutdown partially confirmed'],unknown:['Результат команды неизвестен','Command outcome unknown'],active:['Остановка подтверждена','Shutdown confirmed'],failed:['Команда отклонена · режим не включён','Command rejected · mode not enabled'],restored:['Снятие режима подтверждено','Mode removal confirmed']};
function newTechnical(){return {phase:'off',reason:'',review:null,proof:null,revision:1,operation:null,outcome:'partial',auth:true,error:null,events:[],preview:false,returnRoute:'overview',recovery:false};}
let technical=newTechnical();
const technicalLocked=()=>['pending','partial','unknown','active'].includes(technical.phase);
function technicalAccess(){const g=account?.logged?management.assignments[actor().id]:null;return {read:!!account?.logged&&['ownerA','ownerB','lead','ops','audit'].includes(state.role),activate:!!account?.logged&&['ownerA','ownerB','lead'].includes(state.role)&&!management.revoked&&g?.status==='active'&&(!g.expires||g.expires>management.clock)&&g.environment==='paper'&&g.venue==='both'&&g.rights.includes('emergency.activate')};}
const technicalButton=(ru,en,a,attrs='',primary=false)=>`<button type="button" class="btn${primary?' primary':''}" data-technical="${a}" ${attrs}>${pl(ru,en)}</button>`;
const technicalDigest=()=>JSON.stringify([actor().id,technical.reason.trim(),technical.revision,management.assignments[actor().id]?.revision]);
function technicalError(ru,en){technical.error=[ru,en];return false;}
function technicalChange(value){if(!technicalAccess().activate||technicalLocked())return false;technical.reason=String(value).slice(0,500);technical.revision++;technical.review=null;technical.proof=null;technical.error=null;return true;}
function technicalReview(){technical.proof=null;if(!technicalAccess().activate||technicalLocked()||technical.reason.trim().length<8)return technicalError('Нужны причина от 8 символов и право включить ограничение для всей среды.','A reason of at least 8 characters and permission covering the whole environment are required.');technical.review=technicalDigest();technical.error=null;return true;}
function technicalProof(){technical.proof=null;if(!technicalAccess().activate||!technical.review||technical.review!==technicalDigest()||!technical.auth||!account.protected)return technicalError('Проверка личности не завершена или данные изменились. Вернитесь к проверке последствий.','Identity verification did not complete or data changed. Review effects again.');technical.proof=technicalDigest();return true;}
function technicalSubmit(){if(!technicalAccess().activate||technicalLocked()||!technical.review||technical.review!==technicalDigest()||technical.proof!==technicalDigest())return technicalError('Команда не отправлена: заново проверьте последствия и личность.','Command not sent: review effects and verify identity again.');technical.operation={id:'TECH-DEMO-'+(technical.events.length+1),actor:actor().id,reason:technical.reason.trim(),revision:technical.revision};technical.phase='pending';technical.recovery=false;technical.proof=null;technical.review=null;technical.events.push({actor:actor().id,label:['Запрошено отключение всей среды','Entire environment shutdown requested']});return true;}
function technicalObserve(){if(!technicalAccess().read||!technicalLocked())return false;const next=technical.outcome;if(!['pending','partial','unknown','active','failed'].includes(next))return false;if(technical.operation.confirmedAny&&next==='failed')return false;if(['active','partial'].includes(next))technical.operation.confirmedAny=true;technical.phase=next;technical.events.push({actor:actor().id,label:technicalLabels[next]});return true;}
function technicalStartRecovery(){if(!technicalAccess().read||technical.phase!=='active')return technicalError('Сначала подтвердите состояние всех компонентов. Неизвестный результат нельзя считать остановкой.','Confirm every component first. An unknown outcome is not a confirmed shutdown.');if(!technical.recovery){if(['waiting','approved','unknown'].includes(emergency.status))return technicalError('Сначала завершите уже открытый запрос восстановления. Он не будет перезаписан.','Finish the existing recovery request first. It will not be overwritten.');emergency=newEmergency();emergency.scope='technical';emergency.technicalOperation=technical.operation.id;emergency.returnRoute='technical';technical.recovery=true;}navigate('emergency');return true;}
function technicalRouteAllowed(route){return !technicalLocked()||['entry','technical','profile','incidents','incident','reconciliation','reconciliationItem','emergency'].includes(route);}
function technicalNav(){return technicalAccess().read?technicalButton('Технический режим','Technical mode','open',state.route==='technical'?'aria-current="page"':'').replace('class="btn"','class="sub '+(state.route==='technical'?'selected':'')+'"'):'';}
function technicalAction(a){if(!account?.logged)return false;if(a==='open'){if(!technicalAccess().read)return false;technical.returnRoute=state.route==='technical'?technical.returnRoute:state.route;navigate('technical');return true;}if(!technicalAccess().read)return false;technical.error=null;let result=true;if(a==='review')result=technicalReview();else if(a==='proof')result=technicalProof();else if(a==='submit')result=technicalSubmit();else if(a==='observe')result=technicalObserve();else if(a==='recover'){result=technicalStartRecovery();if(result)return true;}else if(a==='existing'){navigate('emergency');return true;}else if(a==='cancel'){technical.review=null;technical.proof=null;}else if(a==='preview')technical.preview=!technical.preview;else if(a==='back'){navigate(technical.returnRoute);return true;}else return false;render();return result;}
function technicalEffects(){return `<ul class="trading-checks">${[['Приложение и публичный API','App and public API','Доступ будет закрыт','Access will be closed'],['Торговля и деньги через Shadow','Trading and money through Shadow','Новые действия будут запрещены','New actions will be blocked'],['Продуктовые фоновые задания','Product background tasks','Все задания будут остановлены','All tasks will be stopped']].map(([a,b,c,d],i)=>`<li><strong>${pl(a,b)}</strong><span>${technicalLocked()?(technical.phase==='active'||technical.phase==='partial'&&i<2?pl('Подтверждено','Confirmed'):pl('Не подтверждено','Unconfirmed')):pl(c,d)}</span></li>`).join('')}</ul>`;}
function technicalPage(){if(!technicalAccess().read)return heading(pl('Работа временно ограничена','Work temporarily restricted'))+`<p>${pl('В учебной среде запрошен технический режим. Аварийные функции вашему назначению не выданы.','Technical mode was requested in this synthetic environment. Your assignment has no emergency access.')}</p>`+button(t('profile'),'profile');const x=technical,w=technicalAccess().activate,locked=technicalLocked();return heading(pl('Технический режим','Technical mode'),pl('Полное отключение пользовательской части · Paper Alpha · обе площадки','Full user-service shutdown · Paper Alpha · both venues'),!locked?technicalButton('Вернуться к работе','Back to work','back'):'')+`<p class="support-notice" role="status"><strong>${pl(...technicalLabels[x.phase])}</strong>${x.operation?` · ${x.operation.id}`:''}</p>${x.error?`<p class="account-error" role="alert">${pl(...x.error)}</p>${['waiting','approved','unknown'].includes(emergency.status)?technicalButton('Открыть существующее восстановление','Open existing recovery','existing'):''}`:''}<div class="support-layout"><div><section class="panel"><h2>${locked?pl('Проверка остановки','Shutdown verification'):pl('Что отключится','What shuts down')}</h2><p>${pl('Вся учебная среда Shadow: Polymarket и Limitless. Отдельную площадку здесь выбрать нельзя.','The entire synthetic Shadow environment: Polymarket and Limitless. A single venue cannot be selected here.')}</p>${technicalEffects()}${locked?`<p>${pl('Отправка команды ещё не доказывает остановку. При неполном или неизвестном результате проверяйте прежнюю команду; повторной отправки нет.','Submitting a command does not prove shutdown. For partial or unknown results, check the existing command; do not resend.')}</p>${technicalButton('Проверить прежнюю команду','Check existing command','observe','',true)}`:''}</section><section class="panel"><h2>${pl('Что продолжит работать','What remains available')}</h2><p>${pl('Аварийная админка, наблюдение, журнал аудита, инциденты, безопасная сверка и восстановление.','Emergency administration, monitoring, audit log, incidents, safe reconciliation and recovery.')}</p><details><summary>${pl('Что означает безопасная сверка?','What does safe reconciliation mean?')}</summary><p>${pl('Только проверка результатов. Никаких сделок, переводов или повторных заявок. Уже отправленные операции могут завершиться; прямые действия вне Shadow не блокируются.','Checking results only. No trades, transfers or repeated requests. Already-submitted operations may complete; direct actions outside Shadow are not blocked.')}</p></details></section>${locked||x.phase==='restored'?`<section class="panel"><h2>${pl('Восстановление','Recovery')}</h2><p>${pl('Один владелец и другой уполномоченный сотрудник подтверждают одну версию. В учебном назначении это два владельца. Снимается только технический режим; другие запреты сохраняются.','An owner and another authorized employee approve the same revision. In this demo assignment these are the two owners. Only technical mode is removed; other restrictions remain.')}</p>${x.phase==='active'?technicalButton('Подготовить восстановление','Prepare recovery','recover'):''}<p>${pl('Старые заявки не запускаются заново. Восстановительное пополнение требует отдельного разрешения маршрута и подтверждения перевода.','Old requests are not replayed. Recovery funding requires separate route authorization and transfer approval.')}</p></section>`:''}</div><aside class="support-context"><section class="panel"><h2>${locked?pl('Прежняя команда','Existing command'):pl('Включить ограничение','Enable restriction')}</h2>${locked?`<p>${x.operation.id} · ${x.operation.actor}</p><p>${escape(x.operation.reason)}</p>`:w?`<label for="technical-reason">${pl('Причина отключения','Shutdown reason')}</label><textarea id="technical-reason" maxlength="500" rows="3">${escape(x.reason)}</textarea><p class="muted">${pl('8–500 символов. Не указывайте секреты.','8–500 characters. Do not include secrets.')}</p>${x.review?`<p>${pl('Вы отключаете всю среду. Второго подтверждения для усиления ограничения ждать не нужно.','You are shutting down the entire environment. Strengthening a restriction does not wait for a second approval.')}</p><div class="actions">${technicalButton('Проверить личность · учебный ключ','Verify identity · synthetic key','proof')}${technicalButton('Включить технический режим','Enable technical mode','submit',x.proof!==technicalDigest()?'disabled':'',true)}${technicalButton('Отмена','Cancel','cancel')}</div>`:technicalButton('Проверить последствия','Review effects','review','',true)}`:`<p>${pl('Только просмотр. Право включения ограничения не выдано для всей среды.','Read only. Activation permission covering the whole environment is not assigned.')}</p>`}</section><section class="panel"><h2>${pl('Вид для пользователя','User-facing screen')}</h2>${technicalButton(x.preview?'Скрыть пример':'Посмотреть пример',x.preview?'Hide preview':'Show preview','preview')}${x.preview?`<div class="technical-preview"><h3>${pl('Сервис временно недоступен','Service temporarily unavailable')}</h3><p>${pl('Мы восстанавливаем работу. Повторно отправлять операции не нужно.','We are restoring service. Do not resubmit operations.')}</p></div>`:''}<p class="muted">${pl('Пример отображения. Этот прототип не управляет настоящим сервисом.','Display example. This prototype does not control a real service.')}</p></section></aside></div><details class="panel"><summary>${pl('Журнал этого примера','This example’s audit trail')} · ${x.events.length}</summary>${x.events.map(e=>`<p>${e.actor} · ${pl(...e.label)}</p>`).join('')||pl('Команд ещё нет','No commands yet')}</details><details class="panel"><summary>${pl('Учебные результаты проверки','Synthetic check results')}</summary>${feedbackSelect('technical-outcome',pl('Ответ на проверку прежней команды','Response to checking the existing command'),Object.entries(technicalLabels).filter(([k])=>['pending','partial','unknown','active','failed'].includes(k)).map(([k,v])=>[k,pl(...v)]),x.outcome)}<p>${pl('Выбор ответа не меняет состояние. Нажмите «Проверить прежнюю команду».','Choosing a response does not change state. Click “Check existing command”.')}</p></details>`;}
function technicalEmergencyNav(){return technicalAccess().read?technicalNav()+button(t('incidents'),'incidents')+button(t('reconciliation'),'reconciliation')+eb('Аварийное восстановление','Emergency recovery','open')+button(t('profile'),'profile'):button(t('profile'),'profile');}
const technicalBaseEmergencyAction=emergencyAction;
emergencyAction=function(a){const linked=technical.recovery&&emergency.technicalOperation===technical.operation?.id;if(linked&&a==='restart')return false;const result=technicalBaseEmergencyAction(a);if(result&&linked&&emergency.scope==='technical'&&emergency.status==='applied'&&technical.phase!=='restored'){technical.phase='restored';technical.events.push({actor:actor().id,label:['Снятие технического режима подтверждено','Technical mode removal confirmed']});render();}return result;};
const technicalBaseEmergencyChange=emergencyChange;
emergencyChange=function(k,v){if(technical.recovery&&emergency.technicalOperation===technical.operation?.id&&k==='scope')return false;return technicalBaseEmergencyChange(k,v);};
const technicalBaseEmergencyPage=emergencyPage;
emergencyPage=function(){let html=technicalBaseEmergencyPage();if(technical.recovery&&emergency.technicalOperation===technical.operation?.id){if(!emergencyAccess().confirm)html=eb('Выйти и открыть вход владельца','Sign out and open owner sign-in','handoff')+html;html=html.replace('<select id="emergency-scope"','<select disabled id="emergency-scope"');html=html.replace(/<button[^>]*data-emergency="restart"[^>]*>.*?<\/button>/g,'');html=html.replace(/<button[^>]*data-emergency="incident"[^>]*>.*?<\/button>/g,technicalButton('К техническому режиму','Back to technical mode','open'));}return html;};
document.addEventListener('click',e=>{const n=e.target.closest('[data-technical]');if(n&&!n.disabled)technicalAction(n.dataset.technical);});
document.addEventListener('input',e=>{if(e.target.id!=='technical-reason')return;const p=e.target.selectionStart;technicalChange(e.target.value);render();const n=document.querySelector('#technical-reason');n?.focus();n?.setSelectionRange(p,p);});
document.addEventListener('change',e=>{if(e.target.id==='technical-outcome'&&technicalAccess().read)technical.outcome=e.target.value;});
